-- =====================================================================================================================
-- AptRun: DATA seed for the Vault AI Interview + college year-wise cohorts  (NO schema changes - the migrations already ran)
--
-- Fills the new tables / columns that the migrations added but could not fill on their own:
--
--   users.first_login_at, readiness_score, readiness_scored_at, vault_ai_score, vault_ai_scored_at, vault_ai_unlocked_at, graduation_year
--   vault_profiles.ai_interview_score / _stack / _role / _scores / _attempt / _qualified_at
--   vault_interview_qualifications  (new table - filled by students sitting the interview; nothing to seed, see PART A5)
--   student_imports.study_year      (new column - only ever set by a TPO import; old imports correctly stay NULL)
--
-- PART A  generic backfills, work for EVERY college and every student
-- PART B  the Apex Institute demo roster: years of study, 91 extra students (+ their default subscriptions), Alex Chen's unlock
-- PART C  the Vault AI Interview unlock for students who already meet the rule (optional - the app also does it on a visit)
-- PART D  template for setting a real college's years (edit and run for each college)
-- PART E  read-only verification
--
-- SAFE TO RE-RUN: every statement only fills what is still empty (or only moves a value in the right direction) and finds
-- rows by email / college code / plan code - no ids are hard-coded. Take a backup first all the same.
--
--   mysql -u <user> -p <database> < 2026-11-seed-vault-ai-and-year-data.sql
-- =====================================================================================================================

-- 0. PRE-FLIGHT (read-only). The three ids/counts in the first row must not be NULL, or PART B inserts nothing.
SELECT (SELECT id FROM colleges WHERE short_code = 'APEX') AS apex_college_id,
       (SELECT id FROM plans WHERE code = 'coder')          AS coder_plan_id,
       (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'users'
          AND column_name IN ('graduation_year','first_login_at','vault_ai_unlocked_at','readiness_score','readiness_scored_at','vault_ai_score','vault_ai_scored_at')) AS new_user_columns_expected_7;


-- =====================================================================================================================
-- PART A - generic backfills
-- =====================================================================================================================

-- A1. FIRST SIGN-IN. Students who have already used the platform keep their place: their clock is taken to have started when the
--     account was created (the earliest we can honestly say), so nobody restarts the 45 / 90 day wait. Only fills empty values.
UPDATE users SET first_login_at = created_at
 WHERE role = 'user' AND last_seen_at IS NOT NULL AND first_login_at IS NULL;

-- A2. READINESS SCORE kept on the student (for filtering): the latest daily snapshot each student has. Only fills empty values, so it
--     never overwrites a fresher score the app wrote.
UPDATE users u
  JOIN (SELECT s.user_id, s.score
          FROM readiness_snapshots s
          JOIN (SELECT user_id, MAX(snapshot_date) AS d FROM readiness_snapshots GROUP BY user_id) m
            ON m.user_id = s.user_id AND m.d = s.snapshot_date) latest ON latest.user_id = u.id
   SET u.readiness_score = latest.score, u.readiness_scored_at = CURRENT_TIMESTAMP
 WHERE u.readiness_score IS NULL;

-- A3. VAULT AI INTERVIEW SCORE kept on the student: their best series average. Moves a score up, never down. (A series that was
--     failed and already rolled into attempt_history is not in this table's series_average any more; the app keeps the best from the
--     next completed series on.)
UPDATE users u
  JOIN (SELECT user_id, MAX(series_average) AS best
          FROM vault_interview_qualifications WHERE series_average IS NOT NULL GROUP BY user_id) q ON q.user_id = u.id
   SET u.vault_ai_score = q.best, u.vault_ai_scored_at = CURRENT_TIMESTAMP
 WHERE u.vault_ai_score IS NULL OR u.vault_ai_score < q.best;

-- A4. VAULT PROFILE: the interview result that qualified a student, copied onto their Vault profile (only for qualified students
--     who already have a profile, and only while the fields are still empty).
UPDATE vault_profiles p
  JOIN (SELECT q.*
          FROM vault_interview_qualifications q
          JOIN (SELECT user_id, MAX(series_average) AS best FROM vault_interview_qualifications WHERE status = 'qualified' GROUP BY user_id) b
            ON b.user_id = q.user_id AND b.best = q.series_average
         WHERE q.status = 'qualified') q ON q.user_id = p.user_id
   SET p.ai_interview_score = q.series_average, p.ai_interview_stack = q.stack_key, p.ai_interview_role = q.role_key,
       p.ai_interview_scores = q.series_scores, p.ai_interview_attempt = q.current_attempt, p.ai_interview_qualified_at = q.qualified_at
 WHERE p.ai_interview_score IS NULL;

-- A5. vault_interview_qualifications, student_imports.study_year: nothing to seed. The first is one row per student per stack,
--     created when a student opens a stack in the Vault AI Interview; the second is set only by a TPO's year-wise import.


