-- ---------------------------------------------------------------------------------------------------------------------
-- B3. The default individual (Coder) subscription every student gets when the app creates them - for the new students only.
-- ---------------------------------------------------------------------------------------------------------------------
INSERT INTO subscriptions (subscriber_type, subscriber_id, plan_id, status, started_at, is_trial, auto_renew, created_at, updated_at)
SELECT 'App\\Models\\User', u.id, (SELECT id FROM plans WHERE code = 'coder'), 'active', u.created_at, 0, 0, u.created_at, u.created_at
FROM users u WHERE u.email LIKE '%.fill@student.apex.edu'
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.subscriber_type = 'App\\Models\\User' AND s.subscriber_id = u.id);

-- ---------------------------------------------------------------------------------------------------------------------
-- B4. ALEX CHEN: 4th year, CSE / Engineering, past his 45 days, Vault AI Interview unlocked.
--    The earliest first sign-in wins and an unlock already on record is kept, so re-running (or an older record) never moves them.
-- ---------------------------------------------------------------------------------------------------------------------
UPDATE users SET graduation_year = 2027,
  first_login_at = COALESCE(LEAST(first_login_at, '2026-09-08 07:19:43'), '2026-09-08 07:19:43'),
  vault_ai_unlocked_at = COALESCE(vault_ai_unlocked_at, '2026-10-28 07:19:43')
WHERE email = 'alex.chen@student.apex.edu' AND role = 'user';


-- =====================================================================================================================
-- PART C - Vault AI Interview unlock for college students who ALREADY meet the rule. Optional: the app does exactly this, one
-- student at a time, the next time each of them opens the dashboard. Same rule as the app (config/vault_ai.php, config/academic.php):
--   year of study (1-4, from graduation_year) must be 3rd or 4th year; a 4th year (or a batch already passed out) waits 45 days,
--   a 3rd year 90, counted from first_login_at; and readiness_score must be 60 or more. Kept once earned, never taken back.
--   (The academic year starts in July; change @start_month if your ACADEMIC_YEAR_START_MONTH is set to something else.)
-- =====================================================================================================================
SET @min_readiness := 60, @days_4th_year := 45, @days_3rd_year := 90, @programme_years := 4, @start_month := 7;
SET @start_year := IF(MONTH(CURDATE()) >= @start_month, YEAR(CURDATE()), YEAR(CURDATE()) - 1);

UPDATE users
   SET vault_ai_unlocked_at = CURRENT_TIMESTAMP
 WHERE role = 'user' AND college_id IS NOT NULL AND vault_ai_unlocked_at IS NULL
   AND graduation_year IS NOT NULL AND first_login_at IS NOT NULL AND readiness_score >= @min_readiness
   AND (@start_year + @programme_years + 1 - graduation_year) >= 3
   AND first_login_at <= CURRENT_TIMESTAMP - INTERVAL IF((@start_year + @programme_years + 1 - graduation_year) >= @programme_years, @days_4th_year, @days_3rd_year) DAY;


-- =====================================================================================================================
-- PART D - TEMPLATE: set the year of study for a real college. NOT run as it stands (all commented out) - edit, then run per college.
--   graduation_year = the year they pass out. In the 2026-27 academic year: 4th year = 2027, 3rd year = 2028, 2nd year = 2029, 1st year = 2030.
--   A TPO can also do all of this from the Student Cohort page (Set year / import with a year), which is the safer route for a live college.
-- =====================================================================================================================
-- Which colleges still have students with no year:
SELECT c.short_code, c.name, COUNT(*) AS students, SUM(u.graduation_year IS NULL) AS without_year
  FROM users u JOIN colleges c ON c.id = u.college_id
 WHERE u.role = 'user' GROUP BY c.id, c.short_code, c.name ORDER BY without_year DESC;

-- Example: file every student of college 'XYZ' whose roll number starts with '23' under 4th year (2027):
-- UPDATE users SET graduation_year = 2027
--  WHERE role = 'user' AND graduation_year IS NULL AND college_id = (SELECT id FROM colleges WHERE short_code = 'XYZ') AND roll_number LIKE '23%';
-- Example: by branch and section:
-- UPDATE users SET graduation_year = 2028
--  WHERE role = 'user' AND graduation_year IS NULL AND college_id = (SELECT id FROM colleges WHERE short_code = 'XYZ') AND branch_code = 'cse' AND section IN ('A','B');


-- =====================================================================================================================
-- PART E - VERIFY (read-only)
-- =====================================================================================================================
SELECT COUNT(*) AS students, SUM(first_login_at IS NOT NULL) AS with_first_login, SUM(graduation_year IS NOT NULL) AS with_year,
       SUM(readiness_score IS NOT NULL) AS with_readiness, SUM(vault_ai_score IS NOT NULL) AS with_vault_ai_score, SUM(vault_ai_unlocked_at IS NOT NULL) AS vault_ai_unlocked
  FROM users WHERE role = 'user';
SELECT COUNT(*) AS apex_students FROM users WHERE role = 'user' AND college_id = (SELECT id FROM colleges WHERE short_code = 'APEX');
SELECT department, branch_code, SUM(graduation_year = 2029) AS year2, SUM(graduation_year = 2028) AS year3, SUM(graduation_year = 2027) AS year4, COUNT(*) AS total
  FROM users WHERE role = 'user' AND college_id = (SELECT id FROM colleges WHERE short_code = 'APEX') AND branch_code IS NOT NULL GROUP BY department, branch_code ORDER BY department, branch_code;
SELECT email, graduation_year, first_login_at, vault_ai_unlocked_at, readiness_score FROM users WHERE email = 'alex.chen@student.apex.edu';
